 @Test void bkQ08KnownReassessmentFailureRestoresSaveableOriginalExplanation(){UUID id=expense("커피");process(start(preview("ONE",List.of(id),"원래 커피 구매 설명")));var original=draft(id);var failing=new MoneyClassificationProvider(){public Quote quote(Map<String,Object> input){return quoteReady();}public Result classify(Map<String,Object> input){return new Result(null,"확인된 제공자 거절","MOCK","mock","PROVIDER_HTTP_400");}};service=service(failing,BigDecimal.ONE,BigDecimal.TEN,true);UUID run=start(preview("REASSESS",List.of(id),"새 생활용품 설명"));process(run);assertThat(items(run).getFirst()).containsEntry("status","FAILED_KNOWN");var recovered=draft(id);assertThat(recovered).containsEntry("status","ACTIVE").containsEntry("explanation","원래 커피 구매 설명").containsEntry("saveEligible",true);assertThat(recovered.get("active")).isEqualTo(original.get("active"));assertThat(service.usage().get("items")).asList().isNotEmpty();assertThat(savedItem(service.save(new MoneyRecommendationService.Save(UUID.randomUUID(),List.of(saveItem(id,category)))),id)).containsEntry("status","SAVED");}
