 @Test void bkQ08ChangedExplanationInvalidatesCandidateWithoutWritingClassification(){UUID id=expense("커피");process(start(preview("ONE",List.of(id),null)));process(start(preview("REASSESS",List.of(id),"새 구매 설명")));var before=web.bookkeepingRow(id);var d=draft(id);long context=((Number)d.get("contextVersion")).longValue();var edit=new MoneyRecommendationService.ContextEdit(UUID.randomUUID(),context,"다른 구매 설명");var outcome=service.context((UUID)d.get("id"),edit);assertThat(service.context((UUID)d.get("id"),edit)).isEqualTo(outcome);var changed=draft(id);assertThat(changed).containsEntry("contextVersion",context+1).containsEntry("saveEligible",false);assertThat(changed.get("active")).isEqualTo(d.get("active"));assertThat(changed.get("candidate")).isEqualTo(d.get("candidate"));assertThatThrownBy(()->service.decision((UUID)d.get("id"),new MoneyRecommendationService.Decision(UUID.randomUUID(),((Number)d.get("revision")).longValue(),((Number)d.get("candidateRevision")).longValue(),d.get("currentStamp").toString(),context+1,"ADOPT"))).isInstanceOf(InvalidRequestException.class);service.decision((UUID)d.get("id"),new MoneyRecommendationService.Decision(UUID.randomUUID(),((Number)d.get("revision")).longValue(),((Number)d.get("candidateRevision")).longValue(),d.get("currentStamp").toString(),context+1,"KEEP"));assertThat(draft(id)).containsEntry("saveEligible",true);assertThat(web.bookkeepingRow(id)).isEqualTo(before);assertThat(db.queryForObject("select count(*) from money_classification_events",Long.class)).isZero();}
 @Test void bkQ08LateReassessmentCannotOverwriteTypedContext()throws Exception{UUID id=expense("커피");process(start(preview("ONE",List.of(id),null)));var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var blocking=new MoneyClassificationProvider(){public Quote quote(Map<String,Object> input){return quoteReady();}public Result classify(Map<String,Object> input){entered.countDown();try{assertThat(release.await(20,TimeUnit.SECONDS)).isTrue();}catch(InterruptedException e){throw new RuntimeException(e);}return new Result(otherCategory,"합성 후보","MOCK","mock",null,100L,20L,"mock");}};service=service(blocking,BigDecimal.ONE,BigDecimal.TEN,true);UUID run=start(preview("REASSESS",List.of(id),"요청 설명"));UUID item=(UUID)db.queryForList("select id from money_recommendation_items where run_id=?",run).getFirst().get("id");try(var executor=Executors.newSingleThreadExecutor()){var future=executor.submit(()->service.process(owner,item));assertThat(entered.await(20,TimeUnit.SECONDS)).isTrue();var d=draft(id);service.context((UUID)d.get("id"),new MoneyRecommendationService.ContextEdit(UUID.randomUUID(),((Number)d.get("contextVersion")).longValue(),"새로 입력한 설명"));release.countDown();future.get(20,TimeUnit.SECONDS);assertThat(draft(id)).containsEntry("explanation","새로 입력한 설명").containsEntry("status","ACTIVE").containsEntry("saveEligible",false).containsEntry("candidateRevision",null);assertThat(items(run).getFirst()).containsEntry("status","STALE_CONFLICT");assertThat(classification.state(id)).containsEntry("version",0L);}finally{release.countDown();}}

