  UUID refund=product.save(null,new MoneyProductService.Entry(TransactionType.REFUND,null,account,new BigDecimal("10"),original.occurredAt().plusSeconds(3600),"합성 환불",null,null,false,null,null,"환불 연결 필요")).id();
  UUID linkedRefund=product.save(null,new MoneyProductService.Entry(TransactionType.REFUND,null,account,new BigDecimal("10"),original.occurredAt().plusSeconds(3600),"합성 환불",null,null,false,pair,null,"연결된 환불")).id();
  UUID merged=expense("합쳐진 원본");db.update("update money_transactions set merged_into=? where id=?",pair,merged);
  UUID untracked=product.save(null,new MoneyProductService.Entry(TransactionType.EXPENSE,second,null,new BigDecimal("20"),original.occurredAt().plusSeconds(3600),"합성 소비",null,null,false,null,null,"미추적 계좌")).id();
  UUID transfer=product.save(null,new MoneyProductService.Entry(TransactionType.TRANSFER,account,second,new BigDecimal("30"),original.occurredAt().plusSeconds(3600),"합성 이체",null,null,false,null,null,"확정 이체")).id();
  UUID loan=UUID.randomUUID(),payment=UUID.randomUUID(),raw=UUID.randomUUID();db.update("insert into money_loans(id,user_id,name,lender,type,remaining_principal,payment_account_id) values(?,?, '합성 대출','합성 금융사','TEST',1000,?)",loan,owner,account);
  db.update("insert into money_transactions(id,user_id,type,from_account_id,amount,occurred_at,loan_id,title,manual) values(?,?,'LOAN_PAYMENT',?,50,?,?, '대출 분할 필요',true)",payment,owner,account,java.sql.Timestamp.from(original.occurredAt().plusSeconds(3600)),loan);
  db.update("insert into money_raw_notifications(id,user_id,posted_at,raw_payload,dedupe_key,content_hash,state,processing_reason) values(?,?,now(),'{}',?,?,'REVIEW_REQUIRED','POSSIBLE_DUPLICATE')",raw,owner,raw.toString(),raw.toString());
  UUID currentPair=expense("추가 이체 판단 대기");var boundaries=List.of(currentPair,income.id(),refund,linkedRefund,merged,untracked,transfer,payment,raw,account);var factsBefore=db.queryForList("select to_jsonb(t)::text as fact from money_transactions t order by id");
  var blocked=service.run(preview("SELECTED",boundaries,null));assertThat(blocked).containsEntry("total",0L);assertThat(blocked.get("excluded")).asList().hasSize(boundaries.size());
  assertThat(db.queryForList("select to_jsonb(t)::text as fact from money_transactions t order by id")).isEqualTo(factsBefore);assertThat(db.queryForObject("select state from money_raw_notifications where id=?",String.class,raw)).isEqualTo("REVIEW_REQUIRED");assertThat(db.queryForObject("select principal from money_transactions where id=?",BigDecimal.class,payment)).isNull();assertThat(db.queryForObject("select count(*) from money_classification_events",Long.class)).isZero();
  var outsider=new MoneyRecommendationService(db,UUID::randomUUID,json,commands,new MoneyClassificationEngine(db,json,commands),provider,manager,BigDecimal.ONE,BigDecimal.TEN,true);assertThatThrownBy(()->outsider.current(pair)).isInstanceOf(ResourceNotFoundException.class);assertThatThrownBy(()->outsider.draftHistory(pair)).isInstanceOf(ResourceNotFoundException.class);assertThatThrownBy(()->outsider.saved((UUID)db.queryForList("select id from money_recommendation_saves").getFirst().get("id"))).isInstanceOf(ResourceNotFoundException.class);assertThat(outsider.usage().get("items")).asList().isEmpty();
